"""Atlas OS AI — Dedicated Operating System Aware AI Layer.

Provides intelligent intent resolution, authorized OS tool execution,
RAG context augmentation, and LLM inference orchestration.
"""

from __future__ import annotations

import asyncio
import logging
import re
from collections.abc import AsyncIterator
from dataclasses import dataclass, field
from typing import Any

from atlas.ai.tools import ToolRegistry, create_default_tool_registry
from atlas.rag.service import RAGService

logger = logging.getLogger(__name__)


@dataclass
class AtlasAIResponse:
    """Response generated by the Atlas OS AI layer."""
    content: str
    tool_used: str | None = None
    tool_data: Any | None = None
    rag_sources: list[str] = field(default_factory=list)


class AtlasOSAI:
    """The central OS-aware AI layer for Atlas OS.

    Used uniformly across Chat, Voice, and CLI interactions.
    """

    def __init__(
        self,
        ai_manager: Any | None = None,
        rag_service: RAGService | None = None,
        tool_registry: ToolRegistry | None = None,
        container: Any | None = None,
    ) -> None:
        self.ai_manager = ai_manager
        self.container = container
        self.rag_service = rag_service or RAGService()
        self.tool_registry = tool_registry or create_default_tool_registry(
            container=container,
            rag_service=self.rag_service,
        )

    def _match_system_intent(self, text: str) -> tuple[str, dict[str, Any]] | None:
        """Match common user questions directly to approved OS tools."""
        t = text.lower().strip()

        # 1. Model queries
        if any(w in t for w in ("what models", "list models", "show models", "available models", "installed models")):
            return "list_models", {}
        if any(w in t for w in ("loaded model", "active model", "current model", "what model is loaded")):
            return "get_loaded_model", {}

        # 2. System performance & hardware
        if any(w in t for w in ("cpu", "ram usage", "memory usage", "disk usage", "how much ram", "system performance", "system metrics", "uptime")):
            return "get_system_metrics", {}
        if any(w in t for w in ("system info", "os version", "what os", "hostname", "platform info")):
            return "get_system_info", {}

        # 3. Network & Wi-Fi
        if any(w in t for w in ("wifi status", "wi-fi status", "network status", "am i connected", "ip address", "my ip")):
            return "get_network_status", {}
        if any(w in t for w in ("scan wifi", "scan wi-fi", "nearby networks", "scan networks", "available wifi")):
            return "scan_wifi_networks", {}

        # 4. Voice subsystem
        if any(w in t for w in ("voice status", "mic status", "microphone status", "speech status", "tts status")):
            return "get_voice_status", {}

        # 5. Runtime & diagnostics
        if any(w in t for w in ("runtime status", "service health", "services status", "doctor status", "system health")):
            return "get_runtime_status", {}

        # 6. Document / Knowledge search
        rag_patterns = [
            r"search (?:my )?(?:documents|files|knowledge|notes) for (.+)",
            r"look up in (?:documents|notes|knowledge) (.+)",
            r"what do my documents say about (.+)",
            r"find in knowledge base (.+)",
        ]
        for pat in rag_patterns:
            m = re.search(pat, t)
            if m:
                query = m.group(1).strip()
                return "search_knowledge", {"query": query}

        if any(w in t for w in ("list plugins", "what plugins", "installed plugins", "show plugins")):
            return "list_plugins", {}

        return None

    def _format_tool_response(self, tool_name: str, data: Any) -> str:
        """Format raw tool result into a natural, human-friendly response."""
        if tool_name == "list_models":
            if not data:
                return "No AI models are currently registered or downloaded in Atlas OS. You can download one using `atlas models download <model_id>`."
            lines = ["**Installed & Configured Models:**\n"]
            for m in data:
                status = "🟢 Loaded in RAM" if m.get("loaded") else "⚪ Available"
                size = f" ({m.get('size_mb')} MB)" if m.get("size_mb") else ""
                lines.append(f"- **{m.get('model_id')}** [{m.get('provider')}]{size} — {status}")
            return "\n".join(lines)

        elif tool_name == "get_loaded_model":
            if not data.get("loaded"):
                return "No local model is currently loaded in memory. You can load one with `atlas models load <model_id>`."
            return f"**Active Model:** `{data.get('model_id')}` ({data.get('display_name')}) from `{data.get('provider')}` ({data.get('size_mb')} MB)."

        elif tool_name == "get_system_metrics":
            return (
                f"**Atlas OS System Metrics:**\n"
                f"- **CPU Usage:** {data.get('cpu_percent')}%\n"
                f"- **RAM Usage:** {data.get('ram_used_gb')} / {data.get('ram_total_gb')} GB ({data.get('ram_percent')}%)\n"
                f"- **Disk Storage:** {data.get('disk_used_gb')} / {data.get('disk_total_gb')} GB ({data.get('disk_percent')}%)\n"
                f"- **System Uptime:** {data.get('uptime')}"
            )

        elif tool_name == "get_system_info":
            return (
                f"**System Information:**\n"
                f"- **OS:** {data.get('os')} (v{data.get('version')})\n"
                f"- **Hostname:** {data.get('hostname')}\n"
                f"- **Platform:** {data.get('platform')}\n"
                f"- **Architecture:** {data.get('machine')}\n"
                f"- **Python:** {data.get('python_version')}"
            )

        elif tool_name == "get_network_status":
            connected = "Connected 🟢" if data.get("connected") else "Disconnected 🔴"
            ssid = f" (SSID: **{data.get('active_ssid')}**)" if data.get("active_ssid") else ""
            primary = f" via `{data.get('primary_device')}`" if data.get("primary_device") else ""
            
            lines = [f"**Network Status:** {connected}{ssid}{primary}"]
            if data.get("devices"):
                lines.append("\n**Interfaces:**")
                for d in data["devices"]:
                    ip = f" — IP: `{d.get('ip')}`" if d.get("ip") else ""
                    lines.append(f"- `{d.get('iface')}` ({d.get('type')}): {d.get('state')}{ip}")
            return "\n".join(lines)

        elif tool_name == "scan_wifi_networks":
            if not data:
                return "No Wi-Fi access points discovered in the scan."
            lines = ["**Discovered Wi-Fi Networks:**\n"]
            for n in data:
                in_use = " *(Connected)*" if n.get("in_use") else ""
                lines.append(f"- **{n.get('ssid')}** (Signal: {n.get('signal_strength')}%, Security: {n.get('security')}){in_use}")
            return "\n".join(lines)

        elif tool_name == "search_knowledge":
            if not data:
                return "No matching information found in your knowledge base."
            lines = ["**Relevant Knowledge Base Findings:**\n"]
            for idx, r in enumerate(data, 1):
                lines.append(f"**#{idx} [{r.get('doc_title')}]** (Relevance: {r.get('score', 0):.2f})")
                lines.append(f"> {r.get('text', '').strip()}\n")
            return "\n".join(lines)

        elif tool_name == "list_knowledge_documents":
            if not data:
                return "No documents currently indexed in the RAG knowledge base. Ingest documents with `atlas rag ingest <path>`."
            lines = [f"**Indexed Knowledge Base Documents ({len(data)}):**\n"]
            for d in data:
                lines.append(f"- **{d.get('title')}** ({d.get('chunk_count')} chunks, {d.get('doc_id')})")
            return "\n".join(lines)

        elif tool_name == "get_voice_status":
            audio = data.get("audio", {})
            audio_status = "Available 🟢" if audio.get("available") else "Unavailable ⚪"
            return (
                f"**Voice Subsystem Status:**\n"
                f"- **Audio Backend:** {audio.get('backend', 'None')} ({audio_status})\n"
                f"- **Input Devices:** {audio.get('input_devices', 0)}\n"
                f"- **Output Devices:** {audio.get('output_devices', 0)}\n"
                f"- **Wake Word:** {'Ready' if data.get('wake_word', {}).get('available') else 'Not installed'}\n"
                f"- **STT (Speech-to-Text):** {'Ready' if data.get('stt', {}).get('available') else 'Not installed'}\n"
                f"- **TTS (Text-to-Speech):** {'Ready' if data.get('tts', {}).get('available') else 'Not installed'}"
            )

        elif tool_name == "get_runtime_status":
            services = data.get("services", [])
            lines = [f"**Atlas OS Runtime Status:** {data.get('runtime_state', 'running').title()}\n"]
            if services:
                lines.append("**Services:**")
                for s in services:
                    lines.append(f"- `{s.get('name')}`: {s.get('status')} ({s.get('message')})")
            return "\n".join(lines)

        elif tool_name == "list_plugins":
            if not data:
                return "No Atlas OS plugins are currently discovered."
            lines = [f"**Installed Plugins ({len(data)}):**\n"]
            for p in data:
                state = "enabled" if p.get("enabled") else "disabled"
                lines.append(f"- **{p.get('name')}** v{p.get('version')} — {state}")
            return "\n".join(lines)

        return str(data)

    async def process_message(
        self,
        user_message: str,
        session_id: str | None = None,
        model_id: str | None = None,
        **kwargs: Any,
    ) -> AtlasAIResponse:
        """Process a user message through OS tools, RAG, or the LLM inference engine."""
        clean_text = user_message.strip()
        if not clean_text:
            return AtlasAIResponse(content="Please provide a message or question.")

        effective_model = model_id if model_id and model_id not in ("default",) else None

        # 1. Check for direct OS tool intent
        matched_intent = self._match_system_intent(clean_text)
        if matched_intent:
            tool_name, tool_args = matched_intent
            res = await self.tool_registry.execute(tool_name, **tool_args)
            if res.success:
                formatted = self._format_tool_response(tool_name, res.data)
                return AtlasAIResponse(content=formatted, tool_used=tool_name, tool_data=res.data)
            else:
                return AtlasAIResponse(content=f"Error executing {tool_name}: {res.error}", tool_used=tool_name)

        # 2. Check for relevant RAG context
        rag_context = ""
        rag_sources: list[str] = []
        if self.rag_service:
            rag_results = self.rag_service.search(clean_text, top_k=2, threshold=0.15)
            if rag_results:
                rag_context = self.rag_service.build_rag_context(clean_text, top_k=2)
                rag_sources = [r.doc_title for r in rag_results]

        # 3. Route to LLM via AI Manager
        if self.ai_manager is not None:
            prompt_text = clean_text
            if rag_context:
                prompt_text = f"{rag_context}\n\nUser Question: {clean_text}"

            try:
                session = None
                if session_id:
                    try:
                        session = self.ai_manager.get_session(session_id)
                    except Exception:
                        session = None
                if session is None:
                    session = self.ai_manager.new_session(model_id=effective_model)
                    session_id = session.session_id

                chat_res = await self.ai_manager.chat(session_id, prompt_text, **kwargs)
                return AtlasAIResponse(
                    content=chat_res.message.content,
                    rag_sources=rag_sources,
                )
            except Exception as exc:
                logger.warning("AtlasOSAI LLM chat failed: %s", exc)
                if rag_context:
                    return AtlasAIResponse(
                        content=f"Could not reach LLM inference ({exc}), but found relevant knowledge:\n\n{rag_context}",
                        rag_sources=rag_sources,
                    )
                raise

        return AtlasAIResponse(
            content=f"Atlas OS processed message: '{clean_text}'. (LLM provider not configured).",
            rag_sources=rag_sources,
        )

    async def process_stream(
        self,
        user_message: str,
        session_id: str | None = None,
        model_id: str | None = None,
        **kwargs: Any,
    ) -> AsyncIterator[str]:
        """Stream response tokens for user message."""
        clean_text = user_message.strip()
        effective_model = model_id if model_id and model_id not in ("default",) else None
        matched_intent = self._match_system_intent(clean_text)

        if matched_intent:
            tool_name, tool_args = matched_intent
            res = await self.tool_registry.execute(tool_name, **tool_args)
            if res.success:
                formatted = self._format_tool_response(tool_name, res.data)
                for word in formatted.split(" "):
                    yield word + " "
                    await asyncio.sleep(0.005)
                return
            else:
                yield f"Error executing {tool_name}: {res.error}"
                return

        rag_context = ""
        if self.rag_service:
            rag_results = self.rag_service.search(clean_text, top_k=2, threshold=0.15)
            if rag_results:
                rag_context = self.rag_service.build_rag_context(clean_text, top_k=2)

        if self.ai_manager is not None:
            prompt_text = clean_text
            if rag_context:
                prompt_text = f"{rag_context}\n\nUser Question: {clean_text}"

            session = None
            if session_id:
                try:
                    session = self.ai_manager.get_session(session_id)
                except Exception:
                    session = None
            if session is None:
                session = self.ai_manager.new_session(model_id=effective_model)
                session_id = session.session_id

            async for chunk in self.ai_manager.stream_chat(session_id, prompt_text, **kwargs):
                yield chunk
            return

        yield f"Atlas OS: '{clean_text}'"
